   [91]={next_id=92, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="结构还是好的，动力泵也刚被我们的电力接通了——这台升降机还能用。", msg_color="", msg_size=0, talker="涅普露", audio="", img="arts/ui/bg/story/storybg_310.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7197", 0, 0, 65.5, 216.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [92]={next_id=93, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="伴随着低沉的液压声，平台缓缓将你们送上半空。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_310.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [93]={next_id=94, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="控制舱的舱门没有锁，推开门的瞬间，一股混杂着金属和机油味道的干燥空气扑面而来。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_310.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [94]={next_id=95, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="那个人影依然端坐着，神光重科的旧式制服将他生前最后的仪态框定在这把椅子里。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_310.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [95]={next_id=96, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="……您好，前辈。晚辈涅普露，打扰您了。", msg_color="", msg_size=0, talker="涅普露", audio="", img="arts/ui/bg/story/storybg_310.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7197", 0, 0, 65.5, 216.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [96]={next_id=97, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="仿佛听到了涅普露的话，人影缓缓转过了身。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_310.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [97]={next_id=98, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="那是一个中年男人的样貌，在他的胸前，胸针表面的镀层依然在灯光下微微发亮。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_310.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [98]={next_id=99, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="那个胸针……", msg_color="", msg_size=0, talker="涅普露", audio="", img="arts/ui/bg/story/storybg_310.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7197", 0, 0, 65.5, 216.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [99]={next_id=100, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="涅普露掏出自己的胸针，一经对比，发现两者几乎一模一样。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_310.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7197", 0, 0, 65.5, 216.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [100]={next_id=101, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="是你……是你留下了这个胸针，指引我前来的吗？", msg_color="", msg_size=0, talker="涅普露", audio="", img="arts/ui/bg/story/storybg_310.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7197", 0, 0, 65.5, 216.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [101]={next_id=102, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="人影站了起来，如同预想到会有人来此般，注视着你们。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_310.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [102]={next_id=103, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="如果你正在看这段影像，那说明那枚胸针找到了它应该找到的人。", msg_color="", msg_size=0, talker="中年男人", audio="", img="arts/ui/bg/story/storybg_310.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7209", 0, 1, 79, 210}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [103]={next_id=104, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="这很好。这比我预想的任何一种可能性都要好。", msg_color="", msg_size=0, talker="中年男人", audio="", img="arts/ui/bg/story/storybg_310.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7209", 0, 1, 79, 210}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [104]={next_id=105, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="男人顿了顿，那双眼睛直视着镜头，宛如在与你们对话。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_310.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [105]={next_id=106, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="我的名字不重要。我是神光重科的研究主任，代号“Ђ”。", msg_color="", msg_size=0, talker="中年男人", audio="", img="arts/ui/bg/story/storybg_310.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7209", 0, 1, 79, 210}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [106]={next_id=107, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="如果你来自神光重科，你大概知道那意味着什么；如果你不来自神光重科，那就把我当成一个已经消亡的时代的遗老就好。", msg_color="", msg_size=0, talker="Ђ", audio="", img="arts/ui/bg/story/storybg_310.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7209", 0, 1, 79, 210}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [107]={next_id=108, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="百年战争之后，大统领的铁血政策席卷伯基索米，有关黄金时代的一切都在被制度化地清除，而我的研究也理所应当地被列上了清除名单。", msg_color="", msg_size=0, talker="Ђ", audio="", img="arts/ui/bg/story/storybg_310.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7209", 0, 1, 79, 210}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [108]={next_id=109, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="那是我和我的学生们无数个日夜辛苦研究的成果，我没有办法，也没有资格允许自己亲眼看着它被政治的熔炉烧成灰烬。", msg_color="", msg_size=0, talker="Ђ", audio="", img="arts/ui/bg/story/storybg_310.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7209", 0, 1, 79, 210}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [109]={next_id=110, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="于是，我做了一个在所有理智的人看来都毫无胜算的决定——我召集了所有愿意相信我的人，制定了一个计划。", msg_color="", msg_size=0, talker="Ђ", audio="", img="arts/ui/bg/story/storybg_310.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7209", 0, 1, 79, 210}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [110]={next_id=111, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="我称它为——“灯火计划”。", msg_color="", msg_size=0, talker="Ђ", audio="", img="arts/ui/bg/story/storybg_310.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7209", 0, 1, 79, 210}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [111]={next_id=112, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="男人挥动手掌，一座宏伟建筑的蓝图在他身侧展开——那正是眼前这座科学院的完整设计图。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_310.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7209", 0, 1, 79, 210}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [112]={next_id=113, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="你见到的这座科学院中，保留了我们所能带来的所有资料。", msg_color="", msg_size=0, talker="Ђ", audio="", img="arts/ui/bg/story/storybg_310.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7209", 0, 1, 79, 210}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [113]={next_id=114, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="我计划在这里建造一座知识的前哨……一座为探寻未知世界的，灯塔。", msg_color="", msg_size=0, talker="Ђ", audio="", img="arts/ui/bg/story/storybg_310.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7209", 0, 1, 79, 210}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [114]={next_id=115, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="我带领着先遣队先行出发，再由另一支接应队伍，按照留下的信标坐标，在伯基索米重新找到愿意相信这一切的人，带他们来这里汇合。", msg_color="", msg_size=0, talker="Ђ", audio="", img="arts/ui/bg/story/storybg_310.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7209", 0, 1, 79, 210}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [115]={next_id=116, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="我们要在这里建立一座真正意义上的、不被铁血政权荼毒的知识库，让黄金时代的火种，能在这个世界继续燃烧下去。", msg_color="", msg_size=0, talker="Ђ", audio="", img="arts/ui/bg/story/storybg_310.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7209", 0, 1, 79, 210}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [116]={next_id=117, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="他垂下眼帘，原本锐利的目光蒙上了一层黑暗。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_310.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7209", 0, 1, 79, 210}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [117]={next_id=118, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="……我以为，这是一件正确的事。", msg_color="", msg_size=0, talker="Ђ", audio="", img="arts/ui/bg/story/storybg_310.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7209", 0, 1, 79, 210}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [118]={next_id=119, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="但我错误地估计了“等待”两个字，对于人类而言会有多沉重。", msg_color="", msg_size=0, talker="Ђ", audio="", img="arts/ui/bg/story/storybg_310.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7209", 0, 1, 79, 210}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [119]={next_id=120, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="他的声音变得低沉，像是被什么东西压住了。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_310.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7209", 0, 1, 79, 210}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [120]={next_id=121, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="不知道是第几年了，我记不清了。在极北的永夜里，日历很快就变成了毫无意义的废纸。", msg_color="", msg_size=0, talker="Ђ", audio="", img="arts/ui/bg/story/storybg_310.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7209", 0, 1, 79, 210}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [121]={next_id=122, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="补给肉眼可见地减少，恐惧成了所有人心头的重压。", msg_color="", msg_size=0, talker="Ђ", audio="", img="arts/ui/bg/story/storybg_310.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7209", 0, 1, 79, 210}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [122]={next_id=123, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="而接应的信号，始终没有出现。", msg_color="", msg_size=0, talker="Ђ", audio="", img="arts/ui/bg/story/storybg_310.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7209", 0, 1, 79, 210}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [123]={next_id=124, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="Ђ停顿了一下，影像开始出现细微的噪点。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_310.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7209", 0, 1, 79, 210}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [124]={next_id=125, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="恐惧先从边缘开始蔓延。有人提出要回去……有人说要交出我们带走的东西，换取活命的机会……", msg_color="", msg_size=0, talker="Ђ", audio="", img="arts/ui/bg/story/storybg_310.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7209", 0, 1, 79, 210}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [125]={next_id=126, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="有人……开始怀疑是我这个带头人，把所有人骗到这里来送死。", msg_color="", msg_size=0, talker="Ђ", audio="", img="arts/ui/bg/story/storybg_310.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7209", 0, 1, 79, 210}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [126]={next_id=127, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="Ђ的声音依然平静，但他说出的每一个字，都像是在压榨着什么。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_310.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7209", 0, 1, 79, 210}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [127]={next_id=128, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="他们曾经是我亲手引领进入这个领域的学生，是曾经对着自己的研究发过誓的同僚。他们曾经真的相信我，相信自己。", msg_color="", msg_size=0, talker="Ђ", audio="", img="arts/ui/bg/story/storybg_310.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7209", 0, 1, 79, 210}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [128]={next_id=129, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="后来……当“活过今天”成为了所有人大脑里唯一能运转的指令，他们开始争抢当初承载我们进入虚蚀域的航船——“永夜号”的控制权。", msg_color="", msg_size=0, talker="Ђ", audio="", img="arts/ui/bg/story/storybg_310.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7209", 0, 1, 79, 210}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [129]={next_id=130, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="影像里的男人闭上眼睛，深呼吸了很长时间。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_310.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7209", 0, 1, 79, 210}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [130]={next_id=131, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="……意识到将要出现内乱后，我想了很多。", msg_color="", msg_size=0, talker="Ђ", audio="", img="arts/ui/bg/story/storybg_310.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7209", 0, 1, 79, 210}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [131]={next_id=132, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="如果让他们继续争下去，即便最后真的有人坐船离开，也绝不会是最清醒，最值得托付的人，而是这场残酷淘汰中最狠心的人。", msg_color="", msg_size=0, talker="Ђ", audio="", img="arts/ui/bg/story/storybg_310.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7209", 0, 1, 79, 210}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [132]={next_id=133, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="而之后，我更不会相信我们的研究成果，会被带到安全的地方，而不是成为换取大统领宽恕的筹码。", msg_color="", msg_size=0, talker="Ђ", audio="", img="arts/ui/bg/story/storybg_310.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7209", 0, 1, 79, 210}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [133]={next_id=134, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="所以……我做了我唯一能做的事。", msg_color="", msg_size=0, talker="Ђ", audio="", img="arts/ui/bg/story/storybg_310.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7209", 0, 1, 79, 210}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [134]={next_id=135, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="他的目光从镜头移开，定格在某个你们看不到的地方。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_310.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7209", 0, 1, 79, 210}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [135]={next_id=136, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="我启动了能源供给线的紧急切断程序，把所有的能源管线，在同一时间全部物理熔断。", msg_color="", msg_size=0, talker="Ђ", audio="", img="arts/ui/bg/story/storybg_310.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7209", 0, 1, 79, 210}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [136]={next_id=137, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="没有能源，“永夜号”的启动系统无法运转，它永远不会再被开动了。", msg_color="", msg_size=0, talker="Ђ", audio="", img="arts/ui/bg/story/storybg_310.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7209", 0, 1, 79, 210}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [137]={next_id=138, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="我把它永远封存在了这里，也把所有人，把我自己，永远远封存在了这里。", msg_color="", msg_size=0, talker="Ђ", audio="", img="arts/ui/bg/story/storybg_310.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7209", 0, 1, 79, 210}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [138]={next_id=139, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="……他们后来发现了，也彻底爆发了。他们把所有的愤怒和恐惧，全都砸在了彼此的头上。直到最后，动力室再也没有能站着的人了。", msg_color="", msg_size=0, talker="Ђ", audio="", img="arts/ui/bg/story/storybg_310.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7209", 0, 1, 79, 210}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [139]={next_id=140, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="这是这座科学院发生的第一次内乱，而我，杀死了他们。", msg_color="", msg_size=0, talker="Ђ", audio="", img="arts/ui/bg/story/storybg_310.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7209", 0, 1, 79, 210}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [140]={next_id=141, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="——我并不后悔。", msg_color="", msg_size=0, talker="Ђ", audio="", img="arts/ui/bg/story/storybg_310.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7209", 0, 1, 79, 210}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [141]={next_id=142, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="……", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_310.jpg", video_url="", music_id="-1", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [142]={next_id=143, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="影像就此消失 ，四周重新陷入寂静。只有穹顶上的全息星图还在循环播放。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_310.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [143]={next_id=144, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="动力室的疑惑终于得到了答案，而你们仨人却各自凝结了不同的心结。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_310.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
