   [152]={next_id=153, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="虚蚀域危机重重，稍有不慎便会尸骨不存，没有勇气和担当的人，绝对不敢在虚蚀域建立这样一个科学院！", msg_color="", msg_size=0, talker="涅普露", audio="", img="arts/ui/bg/story/storybg_310.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7197", 0, 0, 65.5, 216.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
