   [172]={next_id=173, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="回忆越发清晰，她知道那是“诅咒”正在一点点蚕食她的意志，将她往堕入疯狂的悬崖边上狂推。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_310.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [173]={next_id=174, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="她努力抵抗着侵蚀，她不想现在就成为一个怪物，那样只会伤害到他，伤害到身边的人。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_310.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [174]={next_id=175, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="曾经的她不会有这种想法，但如今，这种信念让她下意识想要这么做。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_310.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [175]={next_id=176, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="她只想完成这最后一件事，让他和他的伙伴安全离开。在那之后，自己便可以安心地坠入“悬崖”，等待死亡降临。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_310.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [176]={next_id=177, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="赫梅克。看着我。", msg_color="", msg_size=0, talker="玩家名字", audio="", img="arts/ui/bg/story/storybg_310.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [177]={next_id=178, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="告诉我，我要怎么帮你。", msg_color="", msg_size=0, talker="玩家名字", audio="", img="arts/ui/bg/story/storybg_310.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [178]={next_id=179, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="他看出来了，自己的灵魂正在饱受煎熬。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_310.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [179]={next_id=180, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="而他眼里的担忧不会骗人，他想要帮自己。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_310.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [180]={next_id=181, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="……我说过了，这是——", msg_color="", msg_size=0, talker="赫梅克", audio="", img="arts/ui/bg/story/storybg_310.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4532", 0, 0, -103, 166.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [181]={next_id=182, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="不要说“这是宿命”。我问的是，现在，这一秒，你需要我做什么？", msg_color="", msg_size=0, talker="玩家名字", audio="", img="arts/ui/bg/story/storybg_310.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4532", 0, 0, -103, 166.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [182]={next_id=183, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="……", msg_color="", msg_size=0, talker="赫梅克", audio="", img="arts/ui/bg/story/storybg_310.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4532", 0, 0, -103, 166.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [183]={next_id=184, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="自己想要接受他的帮助吗？她不知道。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_310.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [184]={next_id=185, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="但至少，在这个时候，自己还不能被记忆里的梦魇击败——因为，和他的赌约还没结束。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_310.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [185]={next_id=186, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="似乎是下意识地，似乎是鬼使神差地，她告诉了他。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_310.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [186]={next_id=187, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="……给我一滴你的血，一滴就好。", msg_color="", msg_size=0, talker="赫梅克", audio="", img="arts/ui/bg/story/storybg_310.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4532", 0, 0, -103, 166.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [187]={next_id=188, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="好。", msg_color="", msg_size=0, talker="玩家名字", audio="", img="arts/ui/bg/story/storybg_310.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [188]={next_id=189, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="你毫不犹豫地用随身的匕首隔开手指，而赫梅克闭上眼睛，任由你将这滴血抹在她的双唇上。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_310.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [189]={next_id=190, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="她将这滴血舔了下去，身体没过多久便有了反应——那些黑色的鳞片暂缓了生长，最终停滞了下来。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_310.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [190]={next_id=191, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="……我感觉好一点了。", msg_color="", msg_size=0, talker="赫梅克", audio="", img="arts/ui/bg/story/storybg_310.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4532", 0, 0, -103, 166.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [191]={next_id=192, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="赫梅克低垂着眼，沉默了一会后，轻声对你说道。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_310.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4532", 0, 0, -103, 166.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [192]={next_id=193, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="……对不起，我并不是想那样反驳涅普露。", msg_color="", msg_size=0, talker="赫梅克", audio="", img="arts/ui/bg/story/storybg_310.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4532", 0, 0, -103, 166.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [193]={next_id=194, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="当我听到那些话的时候，我的内心总会燃起一股无法言说的愤怒，就像是一团无法被浇灭的火焰，在灼烧我的灵魂。", msg_color="", msg_size=0, talker="赫梅克", audio="", img="arts/ui/bg/story/storybg_310.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4532", 0, 0, -103, 166.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [194]={next_id=195, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="我明白，你说的或许没错，但不可否认那段录像的背后存在别的可能，涅普露正是相信了这一点，才会变得激动起来。", msg_color="", msg_size=0, talker="玩家名字", audio="", img="arts/ui/bg/story/storybg_310.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4532", 0, 0, -103, 166.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [195]={next_id=196, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="……嗯。", msg_color="", msg_size=0, talker="赫梅克", audio="", img="arts/ui/bg/story/storybg_310.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4532", 0, 0, -103, 166.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [196]={next_id=197, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="赫梅克，你知道我现在想说什么。", msg_color="", msg_size=0, talker="玩家名字", audio="", img="arts/ui/bg/story/storybg_310.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [197]={next_id=198, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="你和红叶、和尤加利，是不一样的处境——你的侵蚀比她们深得多，放在你身上很可能效果会差很多，甚至根本不够。", msg_color="", msg_size=0, talker="玩家名字", audio="", img="arts/ui/bg/story/storybg_310.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [198]={next_id=199, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="换做以前的我，不会管你接不接受，我都要强行把你救回来。", msg_color="", msg_size=0, talker="玩家名字", audio="", img="arts/ui/bg/story/storybg_310.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [199]={next_id=200, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="但我记得我们的赌约，我想给你选择的权利。", msg_color="", msg_size=0, talker="玩家名字", audio="", img="arts/ui/bg/story/storybg_310.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [200]={next_id=201, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="……", msg_color="", msg_size=0, talker="赫梅克", audio="", img="arts/ui/bg/story/storybg_310.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4532", 0, 0, -103, 166.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
